# Стек: session-контейнер + session-движок (params) → function-транзакция → фабрика
import pytest

@pytest.fixture(scope="session")
def pg_container():
    c = start_postgres()            # 8 с, один раз на прогон
    yield c
    c.stop()

@pytest.fixture(scope="session", params=["postgres", "sqlite"])
def engine(request, pg_container):
    if request.param == "sqlite":
        yield make_engine("sqlite:///:memory:")
    else:
        yield make_engine(pg_container.dsn)   # матрица: каждый зависящий тест бежит дважды

@pytest.fixture
def db(engine):
    conn = engine.connect()
    tx = conn.begin()
    yield conn                      # тесты видят ОДНУ изолированную транзакцию
    tx.rollback()                   # teardown выполняется и при провале
    conn.close()

@pytest.fixture
def make_user(db):
    created = []
    def _make(plan="free", **kw):
        u = insert_user(db, plan=plan, **kw)
        created.append(u)
        return u
    yield _make
    # rollback уже изолирует; явная обратная очистка остаётся для не-транзакционных ресурсов

Скоупы диктует арифметика бюджета: контейнер и движок — session (8 с один раз, а не 53 минуты), а изоляцию даёт function-скоупная фикстура db, чья транзакция откатывается в teardown — каждый тест видит чистую базу по цене begin/rollback, единицы миллисекунд. Инвариант, делающий это безопасным: ничто изменяемое и session-скоупное никогда не попадает в тест напрямую — engine общий, но трактуется как неизменяемый; все записи происходят в потестовой транзакции. Матрица бэкендов живёт в params= фикстуры engine, так что все 400 тестов бегут против обоих бэкендов без дублирования кода — отчёт как test_x[postgres] / test_x[sqlite]. Вариативность тарифов идёт через фабрику make_user, а не через мутацию общего арендатора — тот самый класс отказов от порядка из урока. Единственная autouse-фикстура — гигиена окружения (monkeypatch и так автооткатывается; autouse-фикстура со снимком os.environ страхует от тестов, лезущих в os.environ напрямую) — обоснованно: сквозная изоляция — единственная забота, где невидимость лучше явности.

